mapper.update:
UPDATE users
SET display_name = #{displayName}, phone = #{phone}, avatar = #{avatar}, updated_at = NOW()
WHERE id = #{id}

UPDATE addresses
SET recipient_name = #{recipientName}, phone = #{phone}, province = #{province}, city = #{city}, district = #{district}, detail = #{detail}, is_default = #{isDefault}
WHERE id = #{id} AND user_id = #{userId}

mapper.select:
SELECT * FROM addresses
WHERE user_id = #{userId}
ORDER BY is_default DESC, created_at DESC
LIMIT #{page}, #{size}
